import { canvasScene } from "./core/canvas.js";
let instance;
export function init(container, options = {}) {
  destroy();
  instance = canvasScene(
    container,
    ({ ctx, w, h, t, colors: c }) => {
      const scale = Math.min(w * 0.13, h * 0.12),
        cx = w * 0.5,
        cy = h * 0.63;
      const project = (x, z, y = 0) => [
        cx + (x - z) * scale,
        cy + (x + z) * scale * 0.39 - y * scale,
      ];
      const polygon = (points, fill, stroke) => {
        ctx.beginPath();
        points.forEach((p, i) => (i ? ctx.lineTo(...p) : ctx.moveTo(...p)));
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.fill();
        if (stroke) {
          ctx.strokeStyle = stroke;
          ctx.lineWidth = 0.7;
          ctx.stroke();
        }
      };
      for (let i = -4; i <= 4; i++) {
        ctx.strokeStyle = c.line;
        ctx.globalAlpha = 0.45;
        ctx.beginPath();
        ctx.moveTo(...project(i, -4));
        ctx.lineTo(...project(i, 4));
        ctx.moveTo(...project(-4, i));
        ctx.lineTo(...project(4, i));
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
      polygon(
        [
          project(-2.7, -2.7),
          project(2.7, -2.7),
          project(2.7, 2.7),
          project(-2.7, 2.7),
        ],
        "#172c40",
        "#526579",
      );
      polygon(
        [
          project(2.7, -2.7),
          project(2.7, 2.7),
          project(2.7, 2.7, -0.22),
          project(2.7, -2.7, -0.22),
        ],
        "#0c1724",
        "#3b4c5b",
      );
      polygon(
        [
          project(-2.7, 2.7),
          project(2.7, 2.7),
          project(2.7, 2.7, -0.22),
          project(-2.7, 2.7, -0.22),
        ],
        "#111e2d",
        "#3b4c5b",
      );
      for (let x = -2; x <= 2; x++)
        for (let z = -2; z <= 2; z++) {
          const phase =
            (0.5 + 0.5 * Math.cos(4.2 * Math.hypot(x, z) - t * 2.5)) ** 5;
          polygon(
            [
              project(x - 0.36, z - 0.36, 0.04),
              project(x + 0.36, z - 0.36, 0.04),
              project(x + 0.36, z + 0.36, 0.04),
              project(x - 0.36, z + 0.36, 0.04),
            ],
            `rgb(${50 + phase * 11},${76 + phase * 122},${87 + phase * 142})`,
            "#476172",
          );
          ctx.strokeStyle = "#142b3b";
          ctx.beginPath();
          ctx.moveTo(...project(x - 0.19, z - 0.19, 0.045));
          ctx.lineTo(...project(x - 0.19, z + 0.19, 0.045));
          ctx.lineTo(...project(x + 0.19, z + 0.19, 0.045));
          ctx.lineTo(...project(x + 0.19, z - 0.19, 0.045));
          ctx.stroke();
        }
      for (let i = 0; i < 5; i++) {
        const p = (t * 0.12 + i / 5) % 1;
        ctx.strokeStyle = c.cyan;
        ctx.globalAlpha = 0.4 * Math.sin(p * Math.PI);
        ctx.beginPath();
        ctx.ellipse(
          cx,
          cy - p * h * 0.53,
          8 + p * w * 0.48,
          4 + p * w * 0.15,
          0,
          0,
          Math.PI * 2,
        );
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
      ctx.fillStyle = c.accent;
      ctx.beginPath();
      ctx.arc(cx, cy - 3, 4 + Math.sin(t * 3) * 0.4, 0, Math.PI * 2);
      ctx.fill();
    },
    options,
  );
  return instance;
}
export function destroy() {
  instance?.destroy();
  instance = null;
}
